mapper.select:
SELECT f.id, f.product_id, p.name, p.cover_url, p.price, p.stock, f.created_at, p.category_id FROM product_favorite f JOIN product p ON f.product_id = p.id WHERE f.user_id = #{userId}
AND p.name LIKE CONCAT('%', #{keyword}, '%')
AND p.category_id = #{categoryId}
ORDER BY f.created_at DESC
